# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _check_contactable(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students to build a contact sheet from")
    for student in students:
        if not student.email:
            raise ProjectError(f"no email for {student.display_name}")


def _column_width(cells: Sequence[str]) -> int:
    return max(len(cell) for cell in cells)


# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Rows of name, section and email lined up in columns, sorted by name."""
    _check_contactable(students)
    ordered = sorted(students, key=lambda item: item.display_name)
    name_wide = _column_width([item.display_name for item in ordered])
    sect_wide = _column_width([item.section for item in ordered])
    return [
        f"{item.display_name:<{name_wide}}  {item.section:<{sect_wide}}  {item.email}"
        for item in ordered
    ]

