# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def make_student(last, first, section="A", email="x@example.org"):
    return Student("id-" + last, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = contact_rows([make_student("Zed", "Al"), make_student("Abe", "Bo")])
        self.assertTrue(rows[0].startswith("Abe, Bo"))
        self.assertTrue(rows[1].startswith("Zed, Al"))

    def test_columns_line_up(self):
        rows = contact_rows(
            [
                make_student("Longname", "Pat", "B", "pat@example.org"),
                make_student("Li", "Al", "A", "al@example.org"),
            ]
        )
        self.assertEqual(rows[0], "Li, Al         A  al@example.org")
        self.assertEqual(rows[1], "Longname, Pat  B  pat@example.org")

    def test_missing_email_names_the_student(self):
        students = [make_student("Abe", "Bo"), make_student("Cole", "Dee", email=None)]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(students)
        self.assertIn("Cole, Dee", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make_student("Abe", "Bo", email="")])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
